import prettier from 'eslint-config-prettier';
import path from 'node:path';
import js from '@eslint/js';
import svelte from 'eslint-plugin-svelte';
import { defineConfig, includeIgnoreFile } from 'eslint/config';
import globals from 'globals';
import ts from 'typescript-eslint';

const gitignorePath = path.resolve(import.meta.dirname, '.gitignore');

export default defineConfig(
	includeIgnoreFile(gitignorePath),
	// Generated by buf (npm run gen).
	{ ignores: ['src/lib/gen/'] },
	js.configs.recommended,
	ts.configs.recommended,
	svelte.configs.recommended,
	// oxfmt prints Prettier's style, so these turn off the rules that would fight it.
	prettier,
	svelte.configs.prettier,
	{
		languageOptions: { globals: { ...globals.browser, ...globals.node } },
		rules: {
			// TypeScript already reports undefined names, and no-undef does not know type-only globals.
			'no-undef': 'off'
		}
	},
	{
		// TypeScript inside .svelte files and rune modules. The project service gives three
		// recommended Svelte rules their type information: no-unused-props, require-store-reactive-access
		// (stores imported from other modules) and no-navigation-without-resolve (ResolvedPathname
		// values). It costs about 2 s per run.
		files: ['**/*.svelte', '**/*.svelte.ts', '**/*.svelte.js'],
		languageOptions: {
			parserOptions: {
				projectService: true,
				extraFileExtensions: ['.svelte'],
				parser: ts.parser
			}
		}
	}
);
